# 1. Update src/JavaScript.js
print("Reading src/JavaScript.js...")
with open(SRC_JS, "r", encoding="utf-8") as f:
    content = f.read()

# Replace SUBJECT_EVALUATION_PRESETS definition
pattern = r"const SUBJECT_EVALUATION_PRESETS = \{.*?\};"
if re.search(pattern, content, flags=re.DOTALL):
    content = re.sub(pattern, js_code.strip(), content, flags=re.DOTALL)
    print("Replaced SUBJECT_EVALUATION_PRESETS in src/JavaScript.js successfully!")
else:
    print("Pattern not found in src/JavaScript.js!")

with open(SRC_JS, "w", encoding="utf-8") as f:
    f.write(content)

# Copy to root JavaScript.js
with open(ROOT_JS, "w", encoding="utf-8") as f:
    f.write(content)
print("Copied updated content to root JavaScript.js!")

# 2. Update HTML files by replacing SUBJECT_EVALUATION_PRESETS in inline scripts
html_files = [SRC_INDEX, PUBLIC_INDEX, ROOT_INDEX]
for hfile in html_files:
    if os.path.exists(hfile):
        print(f"Updating {hfile}...")
        with open(hfile, "r", encoding="utf-8") as f:
            hcontent = f.read()
        
        if re.search(pattern, hcontent, flags=re.DOTALL):
            hcontent = re.sub(pattern, js_code.strip(), hcontent, flags=re.DOTALL)
            with open(hfile, "w", encoding="utf-8") as f:
                f.write(hcontent)
            print(f"Updated {hfile} successfully!")
        else:
            print(f"Pattern not found in {hfile}")

print("All files updated with 40 preset items per level!")
